// Supabase database password. Walked through 2026-11-18 (dialog opened and cancelled, nothing reset).
// Page: /dashboard/project/<ref>/database/settings > "Reset password" > dialog with a password box, a
// "Generate a password" link and a "Reset password" button. The password is generated by the provider, read inside this
// script, merged into the existing Npgsql connection string and returned. NEVER screenshot or read text on this page
// while the dialog is open. Resetting ends the old password at once, so there is nothing to revoke afterwards.
import { spawnSync } from "node:child_process";

const PROJECT_REF = "nrbrmtnesldywmgdwdfm";

/** Npgsql values containing ; = or quotes must be quoted, with quotes doubled. */
export function npgsqlValue(password) {
  return /[;="']/.test(password) ? `"${password.replaceAll('"', '""')}"` : password;
}

/** Replaces only the Password= part of a connection string. */
export function withPassword(connectionString, password) {
  if (!/(^|;)\s*Password\s*=/i.test(connectionString)) throw new Error("current connection string has no Password part");
  return connectionString.replace(/(^|;)(\s*Password\s*=)(?:"(?:[^"]|"")*"|[^;]*)/i, (_m, lead, key) => `${lead}${key}${npgsqlValue(password)}`);
}

/** Pulls Host, Port, Username, Database out of an Npgsql string for the psql check. */
export function connectionParts(connectionString) {
  const get = (names) => {
    for (const n of names) {
      const m = new RegExp(`(?:^|;)\\s*${n}\\s*=\\s*([^;]*)`, "i").exec(connectionString);
      if (m) return m[1].trim();
    }
    return "";
  };
  return { host: get(["Host", "Server"]), port: get(["Port"]) || "5432", user: get(["Username", "User Id", "User"]), db: get(["Database"]) || "postgres" };
}

export async function create(page, _entry, { current }) {
  const oldString = current();
  await page.goto(`https://supabase.com/dashboard/project/${PROJECT_REF}/database/settings`);
  await page.getByRole("button", { name: "Reset password" }).first().click();
  const dialog = page.getByRole("dialog", { name: /Reset database password/i });
  await dialog.getByText("Generate a password").click();
  const password = await dialog.locator("input").first().inputValue();
  if (!password || password.length < 16) throw new Error("the generated password looks empty or too short");
  await dialog.getByRole("button", { name: "Reset password" }).click();
  await dialog.waitFor({ state: "hidden", timeout: 60000 });
  return { values: { secret: withPassword(oldString, password) }, oldRef: null };
}

export function check(values) {
  const { host, port, user, db } = connectionParts(values.secret);
  const password = /(?:^|;)\s*Password\s*=\s*(?:"((?:[^"]|"")*)"|([^;]*))/i.exec(values.secret);
  const pw = password?.[1] !== undefined ? password[1].replaceAll('""', '"') : (password?.[2] ?? "");
  const r = spawnSync("psql", ["-h", host, "-p", port, "-U", user, "-d", db, "-tAc", "select 1"], {
    env: { ...process.env, PGPASSWORD: pw, PGSSLMODE: "require" }, encoding: "utf8", timeout: 30000,
  });
  return r.status === 0 && r.stdout.trim() === "1";
}

export function revoke() {
  // The reset replaced the password; there is no old credential left to delete.
}
